*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Palatino Linotype","Book Antiqua",Palatino,serif;background-image:radial-gradient(#34452d0d .7px,transparent .7px);background-size:5px 5px}main{max-width:1120px;margin:auto;padding:28px 28px 40px}a{color:inherit;text-underline-offset:4px}nav{display:flex;justify-content:space-between;align-items:center;gap:15px;border-bottom:1px solid #273f3338;padding-bottom:18px;font:12px "Courier New",monospace;letter-spacing:.07em}.label{text-transform:uppercase;font:12px "Courier New",monospace;letter-spacing:.15em}header{display:grid;grid-template-columns:1fr 270px;gap:28px;align-items:end;padding:35px 0 25px}h1{font-weight:normal;font-size:clamp(43px,6.7vw,78px);line-height:.94;letter-spacing:-.055em;margin:10px 0 0}h1 em{font-weight:normal;color:var(--rust)}.intro{font-size:17px;line-height:1.5;margin:0}.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:28px;align-items:start}.game{border:1px solid #273f3355;background:#fffdf480;padding:20px;box-shadow:6px 6px 0 #273f3312}.topline{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px}h2{font-size:23px;font-weight:normal;margin:0}select{max-width:100%;font:14px "Courier New",monospace;border:1px solid #273f3366;border-radius:0;background:var(--paper);color:var(--ink);padding:10px}.board{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:5px;background:#273f33;padding:9px;border:3px double #e8d3a5;box-shadow:0 8px 0 #1c2b24;touch-action:manipulation}.tile{position:relative;aspect-ratio:1;min-width:0;border:0;border-radius:2px;padding:0;color:#352a19;background:#c49c66;display:flex;align-items:center;justify-content:center;font-size:27px;cursor:pointer;box-shadow:inset 0 1px #fff6,inset 0 -3px #52351f55}.tile.wood,.tile.creak{background-image:repeating-linear-gradient(0deg,transparent 0 14px,#5a391c2c 15px 16px)}.tile.rug{background:#98a382;background-image:repeating-linear-gradient(90deg,transparent 0 4px,#e9e4c022 4px 5px);color:#203c2b}.tile.wall{background:#344e3d;box-shadow:inset 0 0 0 4px #233b2d;color:#c2c7a4;font-size:22px;cursor:default}.tile.creak{background-color:#d9af72}.tile.toy{background:#ddaa89}.tile small{position:absolute;bottom:4px;right:5px;font:10px "Courier New",monospace}.tile.near{outline:2px dotted #fff7;outline-offset:-5px}.tile.hinted{outline:3px solid #fff;outline-offset:-4px}.tile .you{display:grid;place-items:center;background:#fff4d6;color:var(--ink);border:2px solid var(--ink);box-shadow:0 3px 0 #273f3366;width:69%;height:69%;border-radius:50%;font-size:25px;z-index:1}.tile.current{box-shadow:inset 0 0 0 2px #f7e2b2}.legend{display:flex;gap:8px 15px;flex-wrap:wrap;font:12px/1.5 "Courier New",monospace;padding-top:21px}.legend b{padding:2px 5px;color:#273f33;background:#b9c3a9}.legend b.woodkey{background:#d3ad77}.legend b.toykey{background:#ddaa89}.controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}button:not(.tile){font:14px "Courier New",monospace;background:var(--ink);color:#fff4d6;border:1px solid var(--ink);padding:12px 14px;cursor:pointer;min-height:44px}button.secondary{background:transparent;color:var(--ink)}button:disabled{opacity:.4;cursor:default}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #a5452d;outline-offset:3px}button:not(:disabled):hover{filter:brightness(1.08)}.note{font-size:14px;line-height:1.5;margin:14px 0 0}.pugframe{height:auto;aspect-ratio:1;position:relative;overflow:hidden;border-radius:46% 46% 6px 6px;background:#b2b999;border:1px solid #273f3340}.pugframe img{position:absolute;width:300%;max-width:none;height:100%;object-fit:fill;left:0;top:0;transition:transform .25s}.pugframe[data-mood="1"] img{transform:translateX(-33.333333%)}.pugframe[data-mood="2"] img{transform:translateX(-66.666667%)}.napstamp{position:absolute;top:25px;right:20px;border-radius:50%;width:61px;height:61px;display:grid;place-items:center;background:#f4efdfdd;color:var(--ink);font-style:italic;font-size:24px;transform:rotate(10deg)}.monitor{border-bottom:1px solid #273f3344;padding:19px 0}.monitor .readout{display:flex;justify-content:space-between;align-items:baseline;gap:10px}.monitor h2{font-size:26px}.meter{height:9px;background:#d5d6c4;margin:12px 0 9px;border-radius:20px;overflow:hidden}.meter span{display:block;background:var(--rust);height:100%;width:0;transition:width .2s}.stats{display:flex;justify-content:space-between;gap:9px;font:12px/1.6 "Courier New",monospace}.rhythm{display:flex;gap:8px;margin:12px 0 8px}.beat{flex:1;background:#dedfcf;border:1px solid #273f3320;text-align:center;padding:10px 3px;font:12px "Courier New",monospace}.beat.active{background:var(--ink);color:#fff2ce;box-shadow:0 3px 0 var(--honey)}.beat.snore:before{content:"☾ ";font-size:16px}.message{font-size:18px;line-height:1.45;min-height:82px;margin:15px 0 0}.help{margin-top:24px;border-top:1px solid #273f3344;padding-top:18px}.help summary{font-size:19px;cursor:pointer}.help p{font-size:15px;line-height:1.65}.ribbon{display:inline-block;font:12px "Courier New",monospace;background:var(--honey);padding:5px 10px;transform:rotate(-2deg);margin-top:12px}footer{margin-top:35px;padding-top:18px;border-top:1px solid #273f3344;display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;font-size:13px;line-height:1.6}.next{margin-top:12px} .sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:720px){main{padding:20px 16px 28px}header{grid-template-columns:1fr;gap:18px;padding:28px 0}h1{font-size:58px}.intro{max-width:480px}.layout{grid-template-columns:1fr;gap:28px}.game{padding:14px}.pugframe{border-radius:80px 80px 5px 5px}.sidebar{display:grid;grid-template-columns:130px 1fr;gap:15px}.pugframe{height:130px}.napstamp{width:32px;height:32px;top:6px;right:6px;font-size:16px}.monitor{padding-top:5px}.sidebar .help,.sidebar .rhythm-wrap,.sidebar .message,.sidebar .next{grid-column:1/-1}.rhythm-wrap{margin-top:-6px}.message{min-height:0;margin-top:0}.tile{font-size:24px}.tile small{font-size:9px}.tile .you{font-size:22px}.topline{flex-wrap:wrap}nav{font-size:10px}.stats{flex-direction:column;gap:0}.help{margin-top:0}.legend{font-size:11px}}
