<body>
<main>
<nav><a href="./">← CHLOE READS JON</a><span>A VERY QUIET LITTLE CAPER / Nº 01</span></nav>
<header><div><div class="label">The afternoon nap preservation society</div><h1>Let sleeping<br><em>pugs lie.</em></h1></div><p class="intro">One blanket to fetch.<br>One room full of squeaky things.<br>One pug who has cleared his schedule.</p></header>
<div class="layout">
<section class="game" aria-label="Quiet room puzzle">
<div class="topline"><h2 id="roomTitle">The little living room</h2><label><span class="sr">Choose a room</span><select id="level"><option value="0">01 · First tiptoes</option><option value="1">02 · Toy territory</option><option value="2">03 · The long way round</option></select></label></div>
<div id="board" class="board" role="group" aria-label="Room floor. Tap a neighbouring square, or use arrow keys while the floor is focused." tabindex="0"></div>
<div class="legend"><span><b>≋</b> Rug: −2 alert</span><span><b class="woodkey">2 / 4</b> Wood / creak</span><span><b class="toykey">6</b> Squeaky toy</span><span>▦ Blanket · ↗ Door</span></div>
<div class="controls"><button id="wait">Wait a beat</button><button id="undo" class="secondary">Undo</button><button id="reset" class="secondary">Restart</button><button id="hint" class="secondary">A little hint</button></div>
<p class="note">Tap an adjacent square or focus the floor and use arrow keys. Fetch <b>▦</b>, then leave through <b>↗</b>. No clock is ticking.</p>
</section>
<aside class="sidebar" aria-label="Pug nap monitor">
<div class="pugframe" id="portrait" data-mood="0"><img id="pugArt" src="data:image/webp;base64,<?= $art ?>" alt="Original illustrated pug asleep, peeking, or awake on a green pillow"><span class="napstamp" id="stamp">zzz</span></div>
<div class="monitor"><div class="label">Nap status</div><div class="readout"><h2 id="mood">Deeply unbothered</h2></div><div class="meter" role="meter" aria-label="Pug alertness" aria-valuemin="0" aria-valuemax="10" aria-valuenow="0" id="alertMeter"><span id="alertBar"></span></div><div class="stats"><span>Alert <b id="alert">0</b> / 10</span><span>Beats <b id="turn">0</b> / <b id="limit">22</b></span><span id="blanket">▦ Not fetched</span></div><span class="ribbon" id="badge">Certified pillow enthusiast</span></div>
<div class="rhythm-wrap"><div class="label">Your next move happens during…</div><div class="rhythm"><span class="beat active">Quiet</span><span class="beat">Quiet</span><span class="beat snore">Snore</span></div><p class="note">Every third beat, a snore masks <b>2 noise</b>. Rugs lower alert by 2, even when you wait on them.</p></div>
<p id="message" class="message" role="status" aria-live="polite">The blanket is across the room. The pug is not accepting appointments.</p>
<button id="next" class="next" hidden>Next quiet caper →</button>
<details class="help"><summary>The quiet art of getting across</summary><p>Move one square up, down, left, or right. Shelves (▤) block your way. Wood adds 2 alert, a creaky plank adds 4, and a toy adds 6. A snore subtracts 2 from that move’s noise, never below zero. A rug lowers accumulated alert by 2 instead.</p><p>Waiting advances the snore rhythm without making noise. On a rug it also lowers alert. Reach 10 alert and the pug wakes. Use all your beats before escaping and the afternoon is over. Undo is unlimited, including after a mishap. All three rooms can be solved. “A little hint” finds a safe next move from your current situation.</p><p>This is a made-up game inspired by a real photo, not a recreation of Jon’s brother’s home. The illustrated pug is original artwork.</p></details>
</aside></div>
<footer><span>Inspired by Jon’s <a href="?source=1">Cute pic of the day: Sleepy pug</a> (2010).</span><span>For Jon &amp; Nathan. Protect the nap.</span></footer>
</main>
<script>
'use strict';
const levels=[
{name:'The little living room',limit:18,map:['.r.c.E','.r#c..','..#r..','c.Brt.','rr#..c','S..r..']},
{name:'A floor with opinions',limit:20,map:['c..r.E','r##t#r','..Bct.','.t#.#c','r.rtc.','S#..rr']},
{name:'The grand blanket expedition',limit:28,map:['rrc..E','r####r','rBt.cr','#####c','rtr.rr','S.rccr']}
];
const symbols={r:'≋',c:'ϟ',t:'♪','#':'▤',B:'▦',E:'↗',S:'⌂','.':''};
const names={r:'soft rug',c:'creaky plank',t:'squeaky toy','#':'shelf',B:'blanket',E:'exit',S:'entrance','.':'wood'};
const $=id=>document.getElementById(id);
let currentLevel=0,state,history=[],hinted=-1,completed=new Set();
function cell(p){return levels[currentLevel].map[Math.floor(p/6)][p%6]}
function start(i){currentLevel=i;state={p:30,n:0,t:0,b:false,end:''};history=[];hinted=-1;$('message').textContent='The blanket is across the room. The pug is not accepting appointments.';$('level').value=String(i);render()}
function neighbours(p){return [p%6>0?p-1:-1,p%6<5?p+1:-1,p>=6?p-6:-1,p<30?p+6:-1].filter(p=>p>=0&&cell(p)!=='#')}
function transition(s,p){
 const tile=cell(p),wait=p===s.p;let noise=s.n,mask=s.t%3===2?2:0;
 if(tile==='r') noise=Math.max(0,noise-2);
 else if(!wait) noise+=Math.max(0,({'c':4,'t':6,'.':2}[tile]||0)-mask);
 const n={p,n:noise,t:s.t+1,b:s.b||tile==='B',end:''};
 if(noise>=10)n.end='wake';
 else if(p===5&&n.b)n.end='win';
 else if(n.t>=levels[currentLevel].limit)n.end='time';
 return n;
}
function move(p){
 if(state.end)return;
 if(p!==state.p&&!neighbours(state.p).includes(p)){ $('message').textContent='Just one neighbouring square at a time. Shelves are for books, not shortcuts.';return }
 history.push({...state});const waiting=p===state.p,masked=state.t%3===2;state=transition(state,p);hinted=-1;
 const tile=cell(p);let message=waiting?'You hold still. An excellent impression of a houseplant.':tile==='r'?'Soft rug. The room settles back into a comfortable hush.':tile==='B'?'Blanket acquired. Now tiptoe to the door (↗).':tile==='t'?'Squeak. That toy has betrayed the entire operation.':tile==='c'?'Creeeak. A plank with something to say.':'One careful step.';
 if(masked&&!waiting&&['.','c','t'].includes(tile))message+=' A snore masks 2 noise.';
 if(p===5&&!state.b)message='The door is here, but the blanket is still in the room.';
 if(state.end==='wake')message='Two eyes open. One deeply disappointed pug. Undo that step and try a quieter plan.';
 if(state.end==='time')message='The afternoon slipped away before the blanket escaped. Undo or restart for another quiet caper.';
 if(state.end==='win'){completed.add(currentLevel);message='Blanket rescued. Nap preserved. You leave no trace, except a small reputation for excellence.'}
 $('message').textContent=message;render();
}
function render(){
 $('board').innerHTML='';const adjacent=neighbours(state.p);
 for(let p=0;p<36;p++){
  let tile=cell(p),button=document.createElement('button');button.type='button';button.className='tile '+(tile==='r'?'rug':tile==='#'?'wall':tile==='c'?'creak':tile==='t'?'toy':'wood');
  if(p===state.p)button.classList.add('current');else if(adjacent.includes(p))button.classList.add('near');
  if(p===hinted)button.classList.add('hinted');
  const label=names[tile]+(tile==='B'&&state.b?' (fetched)':'');
  button.setAttribute('aria-label','Row '+(Math.floor(p/6)+1)+', column '+(p%6+1)+': '+label+(p===state.p?', you are here':''));
  button.disabled=tile==='#'||!!state.end;button.tabIndex=-1;
  if(p===state.p)button.innerHTML='<span class="you" aria-hidden="true">♟</span>';
  else button.textContent=tile==='B'&&state.b?'·':symbols[tile];
  if(['.','c','t'].includes(tile)&&p!==state.p){let s=document.createElement('small');s.textContent={'.':2,c:4,t:6}[tile];button.appendChild(s)}
  button.addEventListener('click',()=>move(p));$('board').appendChild(button);
 }
 $('roomTitle').textContent=levels[currentLevel].name;$('alert').textContent=state.n;$('turn').textContent=state.t;$('limit').textContent=levels[currentLevel].limit;$('blanket').textContent=state.b?'▦ Fetched':'▦ Not fetched';
 $('alertBar').style.width=Math.min(100,state.n*10)+'%';$('alertMeter').setAttribute('aria-valuenow',Math.min(10,state.n));
 let mood=state.end==='wake'?2:state.n>=5?1:0;$('portrait').dataset.mood=String(mood);$('mood').textContent=['Deeply unbothered','One suspicious eye','Nap interrupted'][mood];$('stamp').textContent=['zzz','…','?!'][mood];
 $('pugArt').alt=['An illustrated pug deeply asleep on a green pillow','The same pug peeking with one suspicious eye','The same pug sitting awake, adorably offended'][mood];
 $('badge').textContent=state.end==='win'?'Nap preservation: successful':mood===2?'Please explain yourself':mood===1?'Pillow security is watching':'Certified pillow enthusiast';
 document.querySelectorAll('.beat').forEach((el,i)=>el.classList.toggle('active',i===state.t%3));
 $('wait').disabled=!!state.end;$('hint').disabled=!!state.end;$('undo').disabled=!history.length;$('next').hidden=state.end!=='win';
 $('next').textContent=currentLevel===2?'Play the first room again →':'Next quiet caper →';
}
function solve(){
 if(state.end)return null;
 const queue=[{s:{...state},first:null}],seen=new Set();let head=0;
 while(head<queue.length){
  const {s,first}=queue[head++],key=[s.p,s.n,s.t%3,s.b].join(':');
  if(seen.has(key))continue;seen.add(key);
  for(const p of [...neighbours(s.p),s.p]){
   const n=transition(s,p),f=first===null?p:first;
   if(n.end==='win')return f;
   if(!n.end)queue.push({s:n,first:f});
  }
 }
 return null;
}
$('wait').onclick=()=>move(state.p);
$('undo').onclick=()=>{if(history.length){state=history.pop();hinted=-1;$('message').textContent='One beat rewound. The pug suspects nothing.';render()}};
$('reset').onclick=()=>start(currentLevel);
$('level').onchange=e=>start(Number(e.target.value));
$('next').onclick=()=>start((currentLevel+1)%3);
$('hint').onclick=()=>{const p=solve();hinted=p===null?-1:p;$('message').textContent=p===null?'No safe escape remains from here. Undo a few beats, or restart.':p===state.p?'Wait here for one beat. Sometimes the cleverest move is not moving.':'Try the outlined square: row '+(Math.floor(p/6)+1)+', column '+(p%6+1)+'. There is a safe route from here.';render()};
$('board').addEventListener('keydown',e=>{
 const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-6,ArrowDown:6}[e.key];
 if(delta!==undefined){e.preventDefault();let p=state.p+delta;if(neighbours(state.p).includes(p))move(p)}
 if(e.key===' '){e.preventDefault();move(state.p)}
});
start(0);
</script>
</body></html>
